for r in records:changes.append(change(D,'societies',r));by_candidate.setdefault(r['candidate_id'],[]).append(r)
for cid,rs in by_candidate.items():
 d=retained_decision(rs[0],rs[0]['qualification_basis'])
 if len(rs)>1:
  assert cid=='c0420'
  d.update(society_ids=[r['id'] for r in rs],source_ids=list(dict.fromkeys(sid for r in rs for sid in r['source_ids'])),split_rationale='The same Ark has two realized eras: human-led access with Monoid servants, then enslaved humans under biological Monoid rulers. Human status, authority and guarantee conditions materially reverse; the final colony is not counted as a third inferred economy.')
 changes.append(change(D,'decisions',d))
assert len(records)==19,len(records)
